// Formula parser and evaluator. AST nodes: num, str, bool, ref, range, un, bin, call.
import { parseAddr, toAddr } from "./addr.mjs";

const REF = /^\$?[A-Za-z]{1,3}\$?[0-9]+/;

function tokenize(text) {
  const toks = [];
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (/\s/.test(ch)) { i++; continue; }
    if (ch === '"') {
      let s = "";
      i++;
      for (;;) {
        if (i >= text.length) throw new SyntaxError("unterminated string");
        if (text[i] === '"') {
          if (text[i + 1] === '"') { s += '"'; i += 2; continue; }
          i++;
          break;
        }
        s += text[i++];
      }
      toks.push({ k: "str", v: s });
      continue;
    }
    const rest = text.slice(i);
    let m = /^(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/.exec(rest);
    if (m) { toks.push({ k: "num", v: Number(m[0]) }); i += m[0].length; continue; }
    m = REF.exec(rest);
    if (m && !/^[A-Za-z0-9_.(]/.test(rest.slice(m[0].length))) {
      toks.push({ k: "ref", v: m[0] });
      i += m[0].length;
      continue;
    }
    m = /^[A-Za-z_][A-Za-z0-9_.]*/.exec(rest);
    if (m) {
      const up = m[0].toUpperCase();
      if (rest[m[0].length] === "(") toks.push({ k: "fn", v: up });
      else if (up === "TRUE" || up === "FALSE") toks.push({ k: "bool", v: up === "TRUE" });
      else throw new SyntaxError(`unexpected name: ${m[0]}`);
      i += m[0].length;
      continue;
    }
    m = /^(<>|<=|>=|[=<>&+\-*\/^(),:])/.exec(rest);
    if (m) { toks.push({ k: "op", v: m[0] }); i += m[0].length; continue; }
    throw new SyntaxError(`unexpected character: ${ch}`);
  }
  return toks;
}

const normRef = (t) => { const a = parseAddr(t); return toAddr(a.col, a.row); };

export function parseFormula(text) {
  const toks = tokenize(String(text));
  let p = 0;
  const peek = () => toks[p];
  const isOp = (...ops) => peek() && peek().k === "op" && ops.includes(peek().v);
  const expect = (v) => {
    if (!isOp(v)) throw new SyntaxError(`expected ${v}`);
    p++;
  };
  const left = (next, ops) => () => {
    let l = next();
    while (isOp(...ops)) {
      const op = toks[p++].v;
      l = { t: "bin", op, l, r: next() };
    }
    return l;
  };
  const primary = () => {
    const t = toks[p++];
    if (!t) throw new SyntaxError("unexpected end");
    if (t.k === "num") return { t: "num", v: t.v };
    if (t.k === "str") return { t: "str", v: t.v };
    if (t.k === "bool") return { t: "bool", v: t.v };
    if (t.k === "ref") {
      if (isOp(":")) {
        p++;
        const u = toks[p++];
        if (!u || u.k !== "ref") throw new SyntaxError("bad range");
        const a = parseAddr(t.v), b = parseAddr(u.v);
        return {
          t: "range",
          c0: Math.min(a.col, b.col), c1: Math.max(a.col, b.col),
          r0: Math.min(a.row, b.row), r1: Math.max(a.row, b.row),
        };
      }
      return { t: "ref", addr: normRef(t.v) };
    }
    if (t.k === "fn") {
      expect("(");
      const args = [];
      if (isOp(")")) p++;
      else {
        for (;;) {
          args.push(compare());
          if (isOp(",")) { p++; continue; }
          expect(")");
          break;
        }
      }
      return { t: "call", name: t.v, args };
    }
    if (t.k === "op" && t.v === "(") {
      const e = compare();
      expect(")");
      return e;
    }
    throw new SyntaxError(`unexpected token: ${t.v}`);
  };
  const unary = () => {
    if (isOp("-", "+")) {
      const op = toks[p++].v;
      return { t: "un", op, x: unary() };
    }
    return primary();
  };
  const power = left(unary, ["^"]);
  const mul = left(power, ["*", "/"]);
  const add = left(mul, ["+", "-"]);
  const cat = left(add, ["&"]);
  const compare = left(cat, ["=", "<>", "<", ">", "<=", ">="]);
  const ast = compare();
  if (p < toks.length) throw new SyntaxError(`unexpected token: ${toks[p].v}`);
  return ast;
}

function rangeAddrs(n) {
  const out = [];
  for (let r = n.r0; r <= n.r1; r++) for (let c = n.c0; c <= n.c1; c++) out.push(toAddr(c, r));
  return out;
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    if (n.t === "ref") seen.add(n.addr);
    else if (n.t === "range") for (const a of rangeAddrs(n)) seen.add(a);
    else if (n.t === "un") walk(n.x);
    else if (n.t === "bin") { walk(n.l); walk(n.r); }
    else if (n.t === "call") n.args.forEach(walk);
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const VALUE = "#VALUE!";

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number") return v;
  const s = v.trim();
  if (s === "") return VALUE;
  const n = Number(s);
  return Number.isFinite(n) ? n : VALUE;
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  return VALUE;
}

const toText = (v) => (v === null ? "" : typeof v === "boolean" ? (v ? "TRUE" : "FALSE") : String(v));

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compareVals(a, b) {
  if (a === null && b === null) { a = 0; b = 0; }
  else if (a === null) a = b === null ? 0 : typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  else if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

const fin = (n) => (Number.isFinite(n) ? n : "#NUM!");

function shift10(n, k) {
  const [m, e] = n.toExponential().split("e");
  return Number(`${m}e${Number(e) + k}`);
}

export function evaluate(ast, lookup) {
  const scalar = (n) => ev(n);
  const ev = (n) => {
    switch (n.t) {
      case "num": case "str": case "bool": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return VALUE;
      case "un": {
        const x = toNum(ev(n.x));
        if (typeof x === "string") return x;
        return n.op === "-" ? fin(-x) : x;
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };
  const binary = (n) => {
    const l = ev(n.l), r = ev(n.r);
    if (isErr(l)) return l;
    if (isErr(r)) return r;
    switch (n.op) {
      case "&": return toText(l) + toText(r);
      case "=": return compareVals(l, r) === 0;
      case "<>": return compareVals(l, r) !== 0;
      case "<": return compareVals(l, r) < 0;
      case ">": return compareVals(l, r) > 0;
      case "<=": return compareVals(l, r) <= 0;
      case ">=": return compareVals(l, r) >= 0;
    }
    const a = toNum(l);
    if (typeof a === "string") return a;
    const b = toNum(r);
    if (typeof b === "string") return b;
    switch (n.op) {
      case "+": return fin(a + b);
      case "-": return fin(a - b);
      case "*": return fin(a * b);
      case "/": return b === 0 ? "#DIV/0!" : fin(a / b);
      case "^": return fin(a ** b);
    }
  };

  // Flattens arguments into values; ranges give their cells (row by row), flagged as from a range.
  const items = (args) => {
    const out = [];
    for (const a of args) {
      if (a.t === "range") for (const addr of rangeAddrs(a)) out.push({ v: lookup(addr), range: true });
      else out.push({ v: ev(a), range: false });
    }
    return out;
  };

  const numbers = (args, forCount) => {
    const nums = [];
    for (const { v, range } of items(args)) {
      if (forCount) { if (typeof v === "number") nums.push(v); continue; }
      if (isErr(v)) return v;
      if (range) { if (typeof v === "number") nums.push(v); continue; }
      const x = toNum(v);
      if (typeof x === "string") return x;
      nums.push(x);
    }
    return nums;
  };

  const logicals = (args) => {
    const out = [];
    for (const { v, range } of items(args)) {
      if (isErr(v)) return v;
      if (range) { if (typeof v === "number" || typeof v === "boolean") out.push(v !== 0 && v !== false); continue; }
      const b = toBool(v);
      if (typeof b === "string") return b;
      out.push(b);
    }
    return out;
  };

  const call = (n) => {
    const args = n.args, c = args.length;
    const name = n.name;
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": case "COUNT": {
        const nums = numbers(args, name === "COUNT");
        if (typeof nums === "string") return nums;
        if (name === "COUNT") return nums.length;
        if (name === "SUM") return fin(nums.reduce((s, x) => s + x, 0));
        if (name === "AVERAGE") return nums.length ? fin(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        if (!nums.length) return 0;
        return nums.reduce((m, x) => (name === "MIN" ? Math.min(m, x) : Math.max(m, x)));
      }
      case "IF": {
        if (c < 2 || c > 3) return VALUE;
        const cond = toBool(scalar(args[0]));
        if (typeof cond === "string") return cond;
        if (cond) return ev(args[1]);
        return c === 3 ? ev(args[2]) : false;
      }
      case "AND": case "OR": {
        if (c < 1) return VALUE;
        const bs = logicals(args);
        if (typeof bs === "string") return bs;
        return name === "AND" ? bs.every(Boolean) : bs.some(Boolean);
      }
      case "NOT": {
        if (c !== 1) return VALUE;
        const b = toBool(ev(args[0]));
        return typeof b === "string" ? b : !b;
      }
      case "ROUND": {
        if (c !== 2) return VALUE;
        const x = toNum(ev(args[0]));
        if (typeof x === "string") return x;
        const d = toNum(ev(args[1]));
        if (typeof d === "string") return d;
        const k = Math.trunc(d);
        if (x === 0) return 0;
        const r = Math.round(shift10(Math.abs(x), k));
        const out = r === 0 ? 0 : shift10(r, -k);
        return fin(x < 0 ? -out : out);
      }
      case "ABS": {
        if (c !== 1) return VALUE;
        const x = toNum(ev(args[0]));
        return typeof x === "string" ? x : Math.abs(x);
      }
      case "LEN": case "UPPER": case "LOWER": {
        if (c !== 1) return VALUE;
        const v = ev(args[0]);
        if (isErr(v)) return v;
        const s = toText(v);
        return name === "LEN" ? s.length : name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let s = "";
        for (const { v } of items(args)) {
          if (isErr(v)) return v;
          s += toText(v);
        }
        return s;
      }
      default: return "#NAME?";
    }
  };
  return ev(ast);
}
