import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { cellAddrs, getCell } from "./sheet.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (t !== "") {
    const n = Number(t);
    if (Number.isFinite(n)) return n;
  }
  const u = raw.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw[0] === "'") return raw.slice(1);
  return raw;
}

// Parses every formula cell: addr -> { ast (null if bad syntax), deps (formula cells read) }.
function analyze(sheet) {
  const nodes = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (raw[0] !== "=") continue;
    let ast = null;
    try { ast = parseFormula(raw.slice(1)); } catch { ast = null; }
    nodes.set(addr, { ast, refs: ast ? refsOf(ast) : [] });
  }
  for (const nd of nodes.values()) nd.deps = nd.refs.filter((a) => nodes.has(a));
  return nodes;
}

// Iterative Tarjan. Returns SCCs, dependencies first.
function sccs(nodes) {
  const index = new Map(), low = new Map(), onStack = new Set();
  const stack = [], out = [];
  let counter = 0;
  for (const root of nodes.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, counter); low.set(root, counter++);
    stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v, i] = frame;
      const deps = nodes.get(v).deps;
      if (i < deps.length) {
        frame[1]++;
        const w = deps[i];
        if (!index.has(w)) {
          index.set(w, counter); low.set(w, counter++);
          stack.push(w); onStack.add(w);
          work.push([w, 0]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) {
          const u = work[work.length - 1][0];
          low.set(u, Math.min(low.get(u), low.get(v)));
        }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const isCyclic = (nodes, comp) => comp.length > 1 || nodes.get(comp[0]).deps.includes(comp[0]);

export function computeAll(sheet) {
  const vals = new Map();
  for (const [addr, raw] of sheet.cells) if (raw[0] !== "=") vals.set(addr, valueOf(raw));
  const nodes = analyze(sheet);
  const lookup = (a) => vals.get(a) ?? null;
  for (const comp of sccs(nodes)) {
    if (isCyclic(nodes, comp)) { for (const a of comp) vals.set(a, "#CYCLE!"); continue; }
    const nd = nodes.get(comp[0]);
    vals.set(comp[0], nd.ast ? evaluate(nd.ast, lookup) : "#ERROR!");
  }
  const out = new Map();
  for (const a of cellAddrs(sheet)) out.set(a, vals.get(a));
  return out;
}

export function dependents(sheet, addr) {
  const a = parseAddr(addr);
  const start = toAddr(a.col, a.row);
  const nodes = analyze(sheet);
  const cyclic = new Set();
  for (const comp of sccs(nodes)) if (isCyclic(nodes, comp)) for (const x of comp) cyclic.add(x);
  const rev = new Map();
  for (const [k, nd] of nodes) for (const d of nd.deps) {
    if (!rev.has(d)) rev.set(d, []);
    rev.get(d).push(k);
  }
  const reach = new Set(), todo = [start];
  while (todo.length) {
    for (const k of rev.get(todo.pop()) ?? []) if (!reach.has(k)) { reach.add(k); todo.push(k); }
  }
  reach.delete(start);
  for (const c of cyclic) reach.delete(c);
  const pos = (k) => { const p = parseAddr(k); return p.row * 1e6 + p.col; };
  const indeg = new Map(), users = new Map();
  for (const k of reach) {
    const ds = nodes.get(k).deps.filter((d) => reach.has(d));
    indeg.set(k, new Set(ds).size);
    for (const d of new Set(ds)) {
      if (!users.has(d)) users.set(d, []);
      users.get(d).push(k);
    }
  }
  const heap = [];
  const push = (k) => {
    heap.push(k);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (pos(heap[p]) <= pos(heap[i])) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let m = i;
        for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && pos(heap[c]) < pos(heap[m])) m = c;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };
  for (const [k, n] of indeg) if (n === 0) push(k);
  const order = [];
  while (heap.length) {
    const k = pop();
    order.push(k);
    for (const u of users.get(k) ?? []) {
      indeg.set(u, indeg.get(u) - 1);
      if (indeg.get(u) === 0) push(u);
    }
  }
  return order;
}
